{
  "name": "Robotiq 三指自适应机械夹爪",
  "name_en": "Robotiq 3-Finger Adaptive Gripper",
  "manufacturer": "Robotiq",
  "description": "这是一种安装在机器人末端的电动三指自适应夹爪，可通过位置、速度、力度和不同抓取模式控制手指运动，以夹持形状各异的工件。它常用于实验室自动化和机器人系统中的样品、器件或治具的抓取、搬运与定位。",
  "description_en": "This is an electric three-finger adaptive robot gripper mounted on a robotic end effector. Its fingers can be controlled by position, speed, force, and grasping mode to handle objects of different shapes. It is commonly used in laboratory automation and robotic systems for grasping, transferring, and positioning samples, parts, or fixtures.",
  "tag_hints": [
    "robot gripper",
    "three-finger gripper",
    "adaptive gripping",
    "robotic sample handling",
    "grasp force control",
    "Modbus control",
    "laboratory automation"
  ],
  "actions": [
    {
      "action_name": "auto-activate",
      "description": "激活夹爪，使其进入可操作状态。",
      "description_en": "Activate the gripper and prepare it for operation."
    },
    {
      "action_name": "auto-command_gripper",
      "description": "按设定的位置、速度、力度和模式控制夹爪执行张开或抓取动作。",
      "description_en": "Control the gripper to open or grasp using the specified position, speed, force, and operating mode."
    },
    {
      "action_name": "auto-status",
      "description": "获取夹爪当前状态。",
      "description_en": "Get the current gripper status."
    },
    {
      "action_name": "auto-close",
      "description": "关闭与夹爪的控制会话。",
      "description_en": "Close the control session with the gripper."
    },
    {
      "action_name": "auto-add_leading_zeros",
      "description": "将夹爪相关二进制数据补零到固定长度。",
      "description_en": "Pad gripper-related binary data with leading zeros to a fixed length."
    },
    {
      "action_name": "auto-Byte_status",
      "description": "解析夹爪状态字节中的各个状态字段。",
      "description_en": "Parse the individual status fields in a gripper status byte."
    },
    {
      "action_name": "auto-stat",
      "description": "解析并定义夹爪的模式与状态位。",
      "description_en": "Parse and define the gripper mode and status bits."
    }
  ]
}

